# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 verbum','词；话语；语法中的动词']]
V=B+[['晚期拉丁 verbalis → 法语 verbal／英语 verbal','与词语有关；语言的、口头的']]
W=[
E('verb','英 /vɜːb/；美 /vɜrb/','动词','在句子里担当核心角色，告诉你发生了什么，或某人某物处于什么状态。','来自法语 verbe 和拉丁 verbum；拉丁词本来泛指词、话语，也有语法上的动词义。',B+[['古法语 verbe → 英语 verb','词；动词 → 现代主要指动词']],'run、think、exist、be 都能作动词，所以“动词就是动作词”只适合最初入门，不能覆盖状态和存在。学 verb 还要看它怎样随时态、人称及句子结构变化。','a regular verb；an irregular verb；a linking verb；verb forms。','word 是单词总称，verb 是词类之一。拉丁 verbum 范围较广，不能用现代英语 verb 的窄义解释所有 verb- 同源词。',('Underline the verb in each sentence.','给每个句子中的动词画下划线。'),('The verb “know” describes a state rather than a visible action.','动词 know 描述的是一种状态，而不是看得见的动作。'),sources=['https://www.etymonline.com/word/verb','https://en.wiktionary.org/wiki/verb']),
E('adverb','英 /ˈædvɜːb/；美 /ˈædvɜrb/','副词','给动作、性质或整句话再补一层说明：怎样、多大程度、何时，或说话者怎么看。','晚期拉丁 ad- 向、附于 + verbum 动词 → adverbium；命名借“加在动词上的词”，现代范围比这个字面更广。',B+[['晚期拉丁 ad + verbum → adverbium','附在动词上、补充动词意义的词'],['英语 adverb','副词']],'在 walk slowly 中 slowly 修饰动作；very tall 中 very 修饰形容词；Fortunately, we arrived 中 fortunately 对整句话作评价。不是所有副词都以 -ly 结尾，例如 often、here。','an adverb of manner；an adverb of frequency；modify an adjective with an adverb。','adverb 是词类名称，adverbial 是句中功能。一个介词短语也可起状语作用，却不因此变成一个副词。',('In “speak clearly,” the adverb describes how someone speaks.','在 speak clearly 中，副词说明说话的方式。'),('The adverb “very” makes the adjective stronger in “very cold.”','在 very cold 中，副词 very 加强了形容词的程度。'),sources=['https://www.etymonline.com/word/adverb','https://en.wiktionary.org/wiki/adverb']),
E('adverbial','英 /ædˈvɜːbiəl/；美 /ædˈvɜrbiəl/','副词的；起状语作用的；状语成分','不只看一个词长什么样，而是看它在句子里是否负责补充时间、地点、方式等信息。','借自晚期拉丁 adverbialis，接 adverbium 副词；现代可联系 adverb + -ial。',B+[['晚期拉丁 adverbium → adverbialis','副词 → 副词相关的'],['英语 adverbial','副词的；作状语的；状语成分']],'an adverbial phrase 是起状语作用的短语。in the morning 在 We left in the morning 中交代时间，虽然是介词短语，却有状语功能；adverbial 因而不局限于一个副词。','an adverbial phrase；an adverbial clause；an adverbial of time。','adverb 是词类，adverbial 多说句法功能；不同语法体系对范围有细节差异，先把“词类”和“作用”分开。',('The phrase “after lunch” functions as an adverbial in this sentence.','短语 after lunch 在这个句子中起状语作用。'),('The teacher asked us to identify the adverbial clause.','老师让我们找出状语从句。'),sources=['https://www.etymonline.com/word/adverbial','https://en.wiktionary.org/wiki/adverbial']),
E('verbal','英 /ˈvɜːbəl/；美 /ˈvɜrbəl/','语言的；口头的；动词的〔语法〕','把意思装进词语里；具体是说出来、写出来，还是语法分类，要看旁边的词。','经法语 verbal 或直接接晚期拉丁 verbalis，来自 verbum 词；不是所有用法都等于英语 verb 动词 + -al。',V,'verbal instructions 通常指口头指示；verbal ability 指理解和运用语言的能力，不只限于开口说话；a verbal noun 则是与动词有关的语法术语。抓住核心“词语相关”，再按场景判断。','verbal instructions；verbal communication；verbal ability；a verbal noun。','oral 明确强调口头；verbal 有更广的语言相关义。与 written 对照时，verbal 常表示口头；与 nonverbal 对照时，往往表示使用语言。',('She gave us verbal instructions before sending the written guide.','她先口头说明，随后发来了书面指南。'),('The test includes both verbal and numerical reasoning tasks.','测试包括语言推理和数字推理任务。'),sources=['https://www.etymonline.com/word/verbal','https://en.wiktionary.org/wiki/verbal']),
E('verbally','英 /ˈvɜːbəli/；美 /ˈvɜrbəli/','口头地；用语言地','把消息说给对方听，或者用词语表达出来，而不是只靠动作和表情。','verbal + -ly；具体是口头还是广义语言方式，随语境变化。',V+[['verbal → verbally','语言的、口头的 → 用语言或口头地']],'explain verbally 通常是口头解释；verbally abusive 是用语言侮辱、攻击他人。读这个副词时要看动词：它说明表达或互动采用了怎样的方式。','communicate verbally；confirm verbally；explain something verbally。','verbally 与 in writing 对照时，强调口头；它不表示逐字原样复述，逐字原样是 verbatim。',('The instructions were explained verbally and then shown on the screen.','说明先口头讲解，随后显示在屏幕上。'),('He confirmed the change verbally during the meeting.','他在会上口头确认了这项变更。'),sources=['https://en.wiktionary.org/wiki/verbally','https://www.etymonline.com/word/verbal']),
E('verbatim','英 /vɜːˈbeɪtɪm/；美 /vərˈbeɪtɪm/','逐字地；一字不改的','像按原稿复印词语，连措辞都保留，不换自己的说法。','来自中世纪拉丁 verbatim；verbum 词 + -atim，形成“逐词地”的副词。',B+[['中世纪拉丁 verbatim','逐词、逐字地'],['英语 verbatim','按原话；一字不改的']],'quote someone verbatim 是逐字引用；a verbatim transcript 是逐字记录。它强调原有措辞被保留，不只是意思相同；把长篇话压缩成摘要通常就不叫 verbatim。','quote verbatim；repeat something verbatim；a verbatim transcript。','verbatim 是原样措辞，paraphrase 是换句话说。verbatim 也不等于“朗读得很生动”或“解释得很准确”。',('The article quoted her final sentence verbatim.','文章一字不改地引用了她最后那句话。'),('This is a summary, not a verbatim transcript of the interview.','这是访谈摘要，不是逐字记录。'),sources=['https://www.etymonline.com/word/verbatim','https://en.wiktionary.org/wiki/verbatim']),
E('verbalize','英 /ˈvɜːbəlaɪz/；美 /ˈvɜrbəlaɪz/','用语言表达；把想法说出来','心里有一团感觉或想法，现在试着把它整理成别人能听懂的话。','现代可认 verbal + -ize；早期英语还受法语 verbaliser 影响，历史上有多说话和使成动词等义。',V+[['法语 verbaliser 与英语 verbal + -ize','形成动词用法'],['现代常见 verbalize','把感受、想法表达成语言']],'verbalize your feelings 是把感受说出来；verbalize a concern 是明确表达担忧。重点不是声音够大，而是把原来未说清的内在想法转成词语。','verbalize feelings；verbalize a concern；struggle to verbalize。','say 是普通说；verbalize 更强调把想法形成语言。语法学中另可表示把词变成动词，需看上下文。',('She found it difficult to verbalize what was bothering her.','她很难把困扰自己的事说清楚。'),('The exercise asks students to verbalize their reasoning.','这个练习要求学生用语言说出自己的推理过程。'),sources=['https://www.etymonline.com/word/verbalize','https://en.wiktionary.org/wiki/verbalize'])
]
